begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
\ir fixtures/finance.inc
create temporary table money_results(k text primary key,v jsonb);grant all on money_results to authenticated;
create function pg_temp.expense(n text,method text,eid uuid) returns jsonb language sql volatile as $$select pg_temp.finance(jsonb_build_object('type','EXPENSE','id',eid,'mutation_id',gen_random_uuid(),'currency','TRY','amount_minor',n,'method',method,'category','SUPPLIES','description','Private synthetic supply expense','stock_receipt_id',null,'external_reference',null,'occurred_at',statement_timestamp(),'reason','Private expense reason'));$$;
create function pg_temp.reverse(eid uuid) returns jsonb language sql volatile as $$select pg_temp.finance(jsonb_build_object('type','REVERSAL','id',gen_random_uuid(),'mutation_id',gen_random_uuid(),'document_id',eid,'reason','Administrative factual correction'));$$;
set local role authenticated;
select is(pg_temp.expense('500','CARD','e5000000-0000-4000-8000-000000000501')#>>'{data,status}','SAVED','expense posts immutable document');
select is(pg_temp.finance_read()#>>'{data,summary,expenses_minor}','500','expense summary exact');
select is(pg_temp.reverse('e5000000-0000-4000-8000-000000000501')#>>'{data,status}','SAVED','expense reversal appends');
select is(pg_temp.finance_read()#>>'{data,summary,expenses_minor}','0','reversed expense summary nets zero');
select is((select amount_minor from public.finance_documents where id='e5000000-0000-4000-8000-000000000501'),500::bigint,'original expense preserved');
select is(pg_temp.expense('200','CASH','e5000000-0000-4000-8000-000000000502')#>>'{data,status}','SAVED','cash expense belongs to open cash session');
select is(pg_temp.finance_read()#>>'{data,cash_sessions,0,current_expected_minor}','9800','cash expense subtracts expected');
select is(pg_temp.finance_read()#>>'{data,cash_sessions,0,cash_out_minor}','200','cash out visible exact');
select is(pg_temp.finance('{"type":"ADJUSTMENT","mutation_id":"e5000000-0000-4000-8000-000000000601","id":"e5000000-0000-4000-8000-000000000503","currency":"TRY","amount_minor":"50","direction":"IN","description":"Measured correction","occurred_at":"2026-10-09T12:00:00Z","reason":"Explicit correction"}')->>'code','CASH_DATE_OUTSIDE_SESSION','cash cannot backdate outside session');
select is(pg_temp.finance_payment('PAYMENT','100','e5000000-0000-4000-8000-000000000504','[]','CASH')#>>'{data,status}','SAVED','explicit unallocated cash credit posts');
select is(pg_temp.finance_read()#>>'{data,cash_sessions,0,current_expected_minor}','9900','opening plus receipts minus expenses exact');
select is(pg_temp.finance_read()#>>'{data,cash_sessions,0,cash_in_minor}','100','cash in exact');
select is(pg_temp.finance('{"type":"CASH_CLOSE_SUBMIT","mutation_id":"e5000000-0000-4000-8000-000000000602","id":"e5000000-0000-4000-8000-000000000101","expected_version":1,"counted_cash_minor":"9850","reason":"Measured shortage"}')#>>'{data,status}','SAVED','close review stores measured count');
select is(pg_temp.finance_read()#>>'{data,cash_sessions,0,difference_minor}','-50','shortage remains explicit');
select is(pg_temp.finance('{"type":"CASH_CLOSE_CONFIRM","mutation_id":"e5000000-0000-4000-8000-000000000603","id":"e5000000-0000-4000-8000-000000000101","expected_version":2,"acknowledge_difference":false,"reason":"Unacknowledged close"}')->>'code','CASH_DIFFERENCE_ACK_REQUIRED','difference requires explicit acknowledgement');
select is(pg_temp.finance_payment('DEPOSIT','1','e5000000-0000-4000-8000-000000000505','[]','CASH')#>>'{data,status}','SAVED','late deposit allowed during review');
select is(pg_temp.finance('{"type":"CASH_CLOSE_CONFIRM","mutation_id":"e5000000-0000-4000-8000-000000000604","id":"e5000000-0000-4000-8000-000000000101","expected_version":3,"acknowledge_difference":true,"reason":"Stale count"}')->>'code','CASH_CLOSE_STALE','late cash rejects stale basis even current version');
select is(pg_temp.finance('{"type":"CASH_CLOSE_SUBMIT","mutation_id":"e5000000-0000-4000-8000-000000000605","id":"e5000000-0000-4000-8000-000000000101","expected_version":3,"counted_cash_minor":"9851","reason":"New measured count"}')#>>'{data,status}','SAVED','new basis accepted');
insert into money_results values('ledger_before',(select to_jsonb(count(*)) from public.finance_ledger_entries));
select is(pg_temp.finance('{"type":"CASH_CLOSE_CONFIRM","mutation_id":"e5000000-0000-4000-8000-000000000606","id":"e5000000-0000-4000-8000-000000000101","expected_version":4,"acknowledge_difference":true,"reason":"Shortage reviewed"}')#>>'{data,status}','SAVED','acknowledged cash close succeeds');
select is((select to_jsonb(count(*)) from public.finance_ledger_entries),(select v from money_results where k='ledger_before'),'close never fabricates balancing movement');
select ok(exists(select 1 from public.audit_events where action='finance.cash_discrepancy_acknowledged'),'discrepancy acknowledgement audited');
select is(pg_temp.reverse('e5000000-0000-4000-8000-000000000504')->>'code','CASH_HISTORY_CLOSED','closed cash financial history cannot be reversed');
select is(pg_temp.finance_payment('PAYMENT','1','e5000000-0000-4000-8000-000000000506','[]','CASH')->>'code','CASH_NOT_OPEN','cash cannot post without active session');
insert into money_results values('retail_command','{"type":"RETAIL_SALE","mutation_id":"e5000000-0000-4000-8000-000000000607","id":"e5000000-0000-4000-8000-000000000507","client_id":"b4000000-0000-4000-8000-000000000031","currency":"TRY","stock_item_id":"c4000000-0000-4000-8000-000000000101","lot_id":null,"quantity":"2","unit_price_minor":"12550","tax_rate_bps":2000,"tax_inclusive":true,"description":"Synthetic retail sale","occurred_at":"2026-10-09T12:00:00Z","reason":"Retail source fact"}');
select is(pg_temp.finance((select v from money_results where k='retail_command'))#>>'{data,status}','SAVED','retail creates financial and stock facts atomically');
select is(pg_temp.finance((select v from money_results where k='retail_command'))#>>'{data,status}','SAVED','retail retry replays permanently');
select is((select count(*) from public.stock_movements where finance_document_id='e5000000-0000-4000-8000-000000000507'),1::bigint,'retail source deducts exactly once');
select is((select sum(quantity_delta) from public.stock_movements where stock_item_id='c4000000-0000-4000-8000-000000000101'),98::numeric,'stock comes from existing ledger');
select is((select amount_minor from public.finance_documents where id='e5000000-0000-4000-8000-000000000507'),25100::bigint,'retail price minor exact');
select is(pg_temp.reverse('e5000000-0000-4000-8000-000000000507')#>>'{data,status}','SAVED','retail administrative reversal restores ledger stock');
select is((select sum(quantity_delta) from public.stock_movements where stock_item_id='c4000000-0000-4000-8000-000000000101'),100::numeric,'stock reversal preserves original deduction');
select throws_ok($$update public.finance_cash_sessions set difference_minor=0$$,'42501',null,'normal user cannot alter cash discrepancy');
select set_config('request.jwt.claim.sub','b4000000-0000-4000-8000-000000000024',true);
select ok(public.finance_snapshot('b4000000-0000-4000-8000-000000000114','b4000000-0000-4000-8000-000000000011','{}') ? 'data','reception may read operational finance');
select is((select count(*) from public.finance_expenses),0::bigint,'reception expenses hidden by RLS');
select is((select count(*) from public.finance_documents where type='EXPENSE' or reversal_of='e5000000-0000-4000-8000-000000000501'),0::bigint,'reception expense originals and reversals hidden');
select is((select count(*) from public.finance_ledger_entries where document_id='e5000000-0000-4000-8000-000000000502'),0::bigint,'reception expense amounts cannot leak through ledger');
select ok(not(public.finance_snapshot('b4000000-0000-4000-8000-000000000114','b4000000-0000-4000-8000-000000000011','{}')#>'{data,cash_sessions,0}' ? 'difference_minor'),'reception cash discrepancy redacted');
select is(public.finance_snapshot('b4000000-0000-4000-8000-000000000114','b4000000-0000-4000-8000-000000000011','{}')#>'{data,summary,expenses_minor}','null'::jsonb,'private expense summary unavailable explicitly');
select is(public.finance_operation('b4000000-0000-4000-8000-000000000114','b4000000-0000-4000-8000-000000000011','{"type":"REVERSAL","mutation_id":"e5000000-0000-4000-8000-000000000608","id":"e5000000-0000-4000-8000-000000000508","document_id":"e5000000-0000-4000-8000-000000000501","reason":"Unauthorized adjustment"}',gen_random_uuid())->>'code','FORBIDDEN','reception cannot correct financial facts');
select * from finish();rollback;
